input.query:
with s as (select subst_sk from t_subst_mstr where subst_nm ilike '%cinacalcet%' or unii_cd ilike 'x'
), m as (select subst_sk from s union select x.subst_sk from x_salt_moiety x join s on x.moiety_subst_sk=s.subst_sk)
select distinct p.prd_cd from t_prd_mstr p join t_prd_ingr i on i.prd_sk=p.prd_sk where i.subst_sk in (select subst_sk from m)

